const f = $('On form submission').first().json;

const brand = (f.brand || '').trim();
const country = (f.country || '').trim();
const competitors = (f.competitors || '')
  .split(',').map(c => c.trim()).filter(c => c);
const queries = (f.queries || '')
  .split('\n').map(q => q.trim()).filter(q => q);

// Validation: stop with a clear message if input is missing
if (!brand || !country || competitors.length === 0 || queries.length === 0) {
  throw new Error('Missing input: brand, country, competitors and queries are required.');
}

// One item per query
return queries.map(query => ({
  json: { brand, competitors, allBrands: [brand, ...competitors], country, query }
}));

const inputs = $('Clean & validate input').all();

return $input.all().map((item, i) => {
  const info = inputs[i].json;
  const organic = item.json.organic || [];

  // Find each brand's position (by title or link)
  const positions = {};
  for (const b of info.allBrands) {
    const key = b.toLowerCase().replace(/\s+/g, '');
    const hit = organic.find(r =>
      (r.title + ' ' + r.link).toLowerCase().replace(/\s+/g, '').includes(key)
    );
    positions[b] = hit ? hit.position : 'not in top 10';
  }

  return {
    json: {
      query: info.query,
      brand: info.brand,
      allBrands: info.allBrands,
      country: info.country,
      google_positions: positions,
      google_top3: organic.slice(0, 3).map(r => r.title),
      google_error: organic.length ? null : 'Serper data missing',
    },
  };
});

const google = $('Extract Google positions').all();

return $input.all().map((item, i) => {
  const g = google[i].json;
  const text = item.json.output?.[0]?.content?.[0]?.text || '';
  const lower = text.toLowerCase();

  // Order in which tracked brands appear in the AI answer
  const found = g.allBrands
    .map(b => ({ b, idx: lower.indexOf(b.toLowerCase()) }))
    .filter(x => x.idx >= 0)
    .sort((a, b) => a.idx - b.idx);

  const ai_mentions = {};
  for (const b of g.allBrands) {
    const rank = found.findIndex(x => x.b === b);
    ai_mentions[b] = rank >= 0 ? `mentioned (#${rank + 1})` : 'not mentioned';
  }

  return {
    json: {
      ...g,
      ai_answer: text,
      ai_mentions,
      ai_error: text ? null : 'AI answer missing',
    },
  };
});

const first = $input.first().json;

return first.allBrands.map(b => ({
  json: { brandName: b }
}));

const brands = $('Brands for news').all().map(i => i.json.brandName);
const queries = $('Combine Google + AI').all().map(i => i.json);

// Keep only news that really mention the brand
const news = {};
$input.all().forEach((item, i) => {
  const b = brands[i];
  const key = b.toLowerCase();
  if (item.json.error) {
    news[b] = 'News data missing (API error)';
    return;
  }
  const relevant = (item.json.articles || [])
    .filter(a => {
      const text = (a.title || '') + ' ' + (a.description || '');
      // Brands written in capitals (e.g. ABOUT YOU) must match exactly
      const strict = b === b.toUpperCase() && b.length > 4;
      return strict ? text.includes(b) : text.toLowerCase().includes(key);
    })
    .slice(0, 3)
    .map(a => ({
      title: a.title,
      source: a.source?.name,
      date: (a.publishedAt || '').slice(0, 10),
      url: a.url,
    }));
  news[b] = relevant.length ? relevant : 'No relevant news found';
});

// Put everything into one package for the report
const first = queries[0];
return [{
  json: {
    brand: first.brand,
    competitors: first.allBrands.slice(1),
    country: first.country,
    date: new Date().toISOString().slice(0, 10),
    results: queries.map(q => ({
      query: q.query,
      google_positions: q.google_positions,
      google_top3: q.google_top3,
      ai_mentions: q.ai_mentions,
      ai_answer: q.ai_answer,
      errors: [q.google_error, q.ai_error].filter(Boolean),
    })),
    news,
  },
}];

const data = $('Build final dataset').first().json;

const guidelines = $input.all().map(i => ({
  source: i.json.document.metadata['pdf.info.Title'] || 'Unknown source',
  text: i.json.document.pageContent,
}));

// ---------- Key facts: comparisons calculated in code ----------
const num = v => (typeof v === 'number' ? v : 99);
const aiRank = s => { const m = /#(\d+)/.exec(s || ''); return m ? +m[1] : 99; };
const b = data.brand;
const key_facts = [];

for (const r of data.results) {
  const q = r.query;

  // Google
  const gB = num(r.google_positions[b]);
  const gWinners = data.competitors.filter(c => num(r.google_positions[c]) < gB);
  if (gB === 99 && gWinners.length === 0) {
    key_facts.push(`Google, "${q}": no tracked brand is in the top 10.`);
  } else if (gWinners.length) {
    key_facts.push(`Google, "${q}": ${gWinners.map(c => `${c} (#${r.google_positions[c]})`).join(', ')} rank above ${b} (${r.google_positions[b]}).`);
  } else {
    key_facts.push(`Google, "${q}": ${b} (#${gB}) ranks above all competitors.`);
  }

  // AI answers
  const aB = aiRank(r.ai_mentions[b]);
  const aWinners = data.competitors.filter(c => aiRank(r.ai_mentions[c]) < aB);
  if (aB === 99 && aWinners.length === 0) {
    key_facts.push(`AI answer, "${q}": no tracked brand is mentioned.`);
  } else if (aWinners.length) {
    key_facts.push(`AI answer, "${q}": ${aWinners.join(', ')} mentioned before ${b}.`);
  } else {
    key_facts.push(`AI answer, "${q}": ${b} is mentioned first among tracked brands.`);
  }
}

// ---------- Visibility score per brand ----------
const total = data.results.length;
const allBrands = [b, ...data.competitors];

const visibility_scores = allBrands.map(brand => {
  const ranked = data.results
    .map(r => r.google_positions[brand])
    .filter(p => typeof p === 'number');
  const mentioned = data.results.filter(r => aiRank(r.ai_mentions[brand]) < 99).length;
  const firstInAI = data.results.filter(r => aiRank(r.ai_mentions[brand]) === 1).length;

  const google_pct = Math.round((ranked.length / total) * 100);
  const ai_pct = Math.round((mentioned / total) * 100);
  const avg_pos = ranked.length
    ? Math.round((ranked.reduce((s, p) => s + p, 0) / ranked.length) * 10) / 10
    : null;

  return {
    brand,
    google_visibility: `${google_pct}%`,
    avg_google_position: avg_pos ?? 'not ranked',
    ai_visibility: `${ai_pct}%`,
    first_among_tracked_in_ai: `${firstInAI} of ${total}`,
    overall_score: `${Math.round((google_pct + ai_pct) / 2)}%`,
  };
});

// Add the scores as facts too, so the fact-checker can verify them
for (const s of visibility_scores) {
  key_facts.push(
    `Score, ${s.brand}: Google visibility ${s.google_visibility}, AI visibility ${s.ai_visibility}, overall ${s.overall_score}.`
  );
}

return [{ json: { ...data, key_facts, visibility_scores, guidelines } }];

const text = $input.first().json.output?.[0]?.content?.[0]?.text || 'Report could not be generated.';
const data = $('Build final dataset').first().json;

return [{
  json: {
    report: text,
    fileName: `${data.brand.toLowerCase().replace(/\s+/g, '_')}_report_${data.date}.md`,
  },
}];

const original = $('Extract report text').first().json;
const check = $input.first().json;

let report, note;
if (check.error || !check.report) {
  // Fact-checker unavailable: keep the original report
  report = original.report;
  note = 'Fact-check: not available (service did not respond), original report used.';
} else {
  report = check.report;
  note = `Fact-check (LangGraph): ${check.status} after ${check.fixes} fix(es).`;
}

return [{
  json: {
    report: `${report}\n\n---\n*${note}*`,
    fileName: original.fileName,
    fact_check_status: check.status || 'unavailable',
  },
}];

const input = $input.first().json;            // report, fileName, fact_check_status
const d = $('Add guidelines').first().json;   // research data + scores
const brands = [d.brand, ...d.competitors];

// ---------- Helpers ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
  .replace(/\[(.+?)\]/g, '<span style="color:#6b7280;font-size:12px;">[$1]</span>');

// Split the Markdown report into sections ("## 1. Summary" etc.)
const sections = {};
input.report.split(/\n(?=## )/).forEach(block => {
  const m = block.match(/^## \d+\.\s*(.+)/);
  if (m) sections[m[1].trim().toLowerCase()] = block.split('\n').slice(1).join('\n').trim();
});
const getSec = name => Object.entries(sections).find(([k]) => k.startsWith(name))?.[1] || '';

// Small Markdown -> HTML (paragraphs, bullets, numbered lists; tables are skipped)
function mdToHtml(md) {
  const lines = md.split('\n').filter(l =>
    !l.trim().startsWith('|') && !l.startsWith('---') && !l.startsWith('*Fact-check'));
  let html = '', list = null;
  const close = () => { if (list) { html += `</${list}>`; list = null; } };
  for (const raw of lines) {
    const l = raw.trim();
    if (!l) { close(); continue; }
    let m;
    if ((m = l.match(/^[-*]\s+(.*)/))) {
      if (list !== 'ul') { close(); html += '<ul style="padding-left:20px;margin:8px 0;">'; list = 'ul'; }
      html += `<li style="margin:6px 0;">${inline(m[1])}</li>`;
    } else if ((m = l.match(/^\d+\.\s+(.*)/))) {
      if (list !== 'ol') { close(); html += '<ol style="padding-left:20px;margin:8px 0;">'; list = 'ol'; }
      html += `<li style="margin:6px 0;">${inline(m[1])}</li>`;
    } else {
      close();
      html += `<p style="margin:8px 0;">${inline(l)}</p>`;
    }
  }
  close();
  return html;
}

// ---------- Building blocks ----------
const pct = s => parseInt(s) || 0;
const bar = (value, color) => `
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#eef0f4;border-radius:6px;"><tr>
    <td width="${Math.max(value, 1)}%" style="background:${color};height:10px;border-radius:6px;font-size:0;line-height:0;">&nbsp;</td>
    <td style="font-size:0;line-height:0;">&nbsp;</td>
  </tr></table>`;

const th = t => `<th style="background:#f3f4f6;padding:8px;font-size:12px;text-align:left;color:#374151;">${esc(t)}</th>`;
const td = (content, bg = '#ffffff', color = '#111827') =>
  `<td style="padding:8px;font-size:13px;background:${bg};color:${color};border-bottom:1px solid #eef0f4;">${content}</td>`;
const gCell = p => typeof p === 'number'
  ? (p <= 3 ? td('#' + p, '#dcfce7', '#166534') : td('#' + p, '#fef9c3', '#854d0e'))
  : td('—', '#fee2e2', '#991b1b');
const aCell = m => {
  const r = /#(\d+)/.exec(m || '');
  if (!r) return td('—', '#fee2e2', '#991b1b');
  return r[1] === '1' ? td('✔ #1', '#dcfce7', '#166534') : td('✔ #' + r[1], '#ecfdf5', '#065f46');
};
const section = (title, body) => `
  <tr><td style="padding:24px 32px;border-top:1px solid #eef0f4;">
    <h2 style="margin:0 0 12px;font-size:18px;color:#111827;">${title}</h2>${body}
  </td></tr>`;

// ---------- Score cards ----------
const scoreRows = (d.visibility_scores || []).map(s => {
  const main = s.brand === d.brand;
  const cell = 'padding:10px 8px;border-bottom:1px solid #eef0f4;';
  return `<tr>
    <td style="${cell}font-weight:${main ? '700' : '400'};color:${main ? '#4f46e5' : '#111827'};white-space:nowrap;">${esc(s.brand)}</td>
    <td style="${cell}width:30%;">${bar(pct(s.google_visibility), '#3b82f6')}
      <div style="font-size:12px;color:#6b7280;margin-top:4px;">${esc(s.google_visibility)} · avg pos ${esc(s.avg_google_position)}</div></td>
    <td style="${cell}width:30%;">${bar(pct(s.ai_visibility), '#10b981')}
      <div style="font-size:12px;color:#6b7280;margin-top:4px;">${esc(s.ai_visibility)} · first ${esc(s.first_among_tracked_in_ai)}</div></td>
    <td style="${cell}text-align:center;font-size:20px;font-weight:700;color:#111827;">${esc(s.overall_score)}</td>
  </tr>`;
}).join('');
const scoreTable = `
  <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
    <tr>${th('Brand')}${th('Google')}${th('AI answers')}${th('Overall')}</tr>${scoreRows}
  </table>
  <p style="font-size:12px;color:#6b7280;margin-top:8px;">Google = share of queries in the top 10. AI = share of AI answers mentioning the brand.</p>`;

// ---------- Google & AI tables ----------
const headerRow = `<tr>${th('Query')}${brands.map(th).join('')}</tr>`;
const googleTable = `
  <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">${headerRow}
    ${d.results.map(r => `<tr>${td(esc(r.query))}${brands.map(b => gCell(r.google_positions[b])).join('')}</tr>`).join('')}
  </table>
  <p style="font-size:12px;color:#6b7280;margin-top:8px;">Green = top 3 · Yellow = #4–10 · Red = not in top 10</p>`;
const aiTable = `
  <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">${headerRow}
    ${d.results.map(r => `<tr>${td(esc(r.query))}${brands.map(b => aCell(r.ai_mentions[b])).join('')}</tr>`).join('')}
  </table>
  <p style="font-size:12px;color:#6b7280;margin-top:8px;">✔ #1 = first among tracked brands · — = not mentioned</p>`;

// ---------- News ----------
const newsHtml = brands.map(b => {
  const items = d.news?.[b];
  const list = Array.isArray(items)
    ? items.slice(0, 2).map(n => `<li style="margin:4px 0;">
        <a href="${esc(n.url)}" style="color:#4f46e5;text-decoration:none;">${esc(n.title)}</a>
        <span style="color:#9ca3af;font-size:12px;"> ${esc(n.source)}, ${esc(n.date)}</span></li>`).join('')
    : `<li style="color:#9ca3af;">${esc(items || 'No news')}</li>`;
  return `<p style="margin:12px 0 4px;font-weight:700;">${esc(b)}</p><ul style="padding-left:20px;margin:0;font-size:13px;">${list}</ul>`;
}).join('');

// ---------- Fact-check badge ----------
const passed = input.fact_check_status === 'passed';
const badge = `<span style="background:${passed ? '#dcfce7' : '#ffedd5'};color:${passed ? '#166534' : '#9a3412'};padding:4px 10px;border-radius:12px;font-size:12px;font-weight:700;">Fact-check: ${esc(input.fact_check_status)}</span>`;

// ---------- Full email ----------
const html = `
<div style="background:#f3f4f6;padding:24px 0;font-family:Arial,Helvetica,sans-serif;">
<table width="100%" align="center" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;max-width:640px;margin:0 auto;">
  <tr><td style="background:#4f46e5;padding:28px 32px;color:#ffffff;border-radius:12px 12px 0 0;">
    <div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;">AI Search Visibility Report</div>
    <div style="font-size:24px;font-weight:700;margin-top:6px;">${esc(d.brand)} vs Competitors</div>
    <div style="font-size:13px;margin-top:8px;">${esc(d.date)} · ${esc(d.country)} · ${d.results.length} queries checked</div>
  </td></tr>
  <tr><td style="padding:16px 32px 0;">${badge}</td></tr>
  ${section('Summary', mdToHtml(getSec('summary')))}
  ${section('Visibility Score', scoreTable)}
  ${section('Google Visibility', googleTable)}
  ${section('AI Answer Visibility', aiTable)}
  ${section('Gaps & Opportunities', mdToHtml(getSec('gaps')))}
  ${section('Recommendations', mdToHtml(getSec('recommendations')))}
  ${section('News & Brand Signals', newsHtml)}
  <tr><td style="padding:20px 32px;background:#f9fafb;font-size:12px;color:#6b7280;border-radius:0 0 12px 12px;">
    Sources: Serper (Google results), OpenAI (AI answer check), NewsAPI (news), Pinecone (SEO/GEO guidelines).<br>
    Full report attached as a Markdown file. Generated automatically by the AI Search Visibility Agent.
  </td></tr>
</table>
</div>`;

return [{ json: { ...input, html } }];
